templates.compose:
services:
  9router:
    image: decolua/9router:latest
    restart: unless-stopped
    environment:
      DATA_DIR: /app/data
      INITIAL_PASSWORD: ${INITIAL_PASSWORD}
      JWT_SECRET: ${JWT_SECRET}
      API_KEY_SECRET: ${API_KEY_SECRET}
      MACHINE_ID_SALT: ${MACHINE_ID_SALT}
      NEXT_PUBLIC_BASE_URL: ${BASE_URL}
    volumes:
      - 9router-data:/app/data
volumes:
  9router-data:

services:
  # Routes the web app, API, auth and file links on one domain.
  nginx:
    image: nginx:1.29-alpine
    restart: unless-stopped
    configs:
      - source: nginx-conf
        target: /etc/nginx/nginx.conf
    depends_on:
      - appflowy_cloud
      - gotrue
      - admin_frontend
      - appflowy_web
  appflowy_web:
    image: appflowyinc/appflowy_web:latest
    restart: unless-stopped
    environment:
      APPFLOWY_BASE_URL: ${APPFLOWY_URL}
      APPFLOWY_GOTRUE_BASE_URL: ${APPFLOWY_URL}/gotrue
      APPFLOWY_WS_BASE_URL: wss://${APPFLOWY_HOST}/ws/v2
    depends_on:
      appflowy_cloud:
        condition: service_healthy
  appflowy_cloud:
    image: appflowyinc/appflowy_cloud:latest
    restart: unless-stopped
    environment:
      RUST_LOG: info
      APPFLOWY_ENVIRONMENT: production
      APPFLOWY_DATABASE_URL: postgres://postgres:${DB_PASSWORD}@postgres:5432/postgres
      APPFLOWY_REDIS_URI: redis://redis:6379
      APPFLOWY_GOTRUE_JWT_SECRET: ${JWT_SECRET}
      APPFLOWY_GOTRUE_BASE_URL: http://gotrue:9999
      APPFLOWY_S3_CREATE_BUCKET: "true"
      APPFLOWY_S3_USE_MINIO: "true"
      APPFLOWY_S3_MINIO_URL: http://minio:9000
      APPFLOWY_S3_ACCESS_KEY: minio
      APPFLOWY_S3_SECRET_KEY: ${MINIO_PASSWORD}
      APPFLOWY_S3_BUCKET: appflowy
      APPFLOWY_S3_REGION: us-east-1
      APPFLOWY_S3_PRESIGNED_URL_ENDPOINT: ${APPFLOWY_URL}/minio-api
      APPFLOWY_ACCESS_CONTROL: "true"
      APPFLOWY_DATABASE_MAX_CONNECTIONS: "40"
      APPFLOWY_WEB_URL: ${APPFLOWY_URL}
      APPFLOWY_BASE_URL: ${APPFLOWY_URL}
      APPFLOWY_SEARCH_SERVICE_URL: http://appflowy_search:4002
      AI_ENABLED: "false"
    depends_on:
      gotrue:
        condition: service_healthy
      minio:
        condition: service_healthy
      redis:
        condition: service_healthy
    healthcheck:
      test: ["CMD-SHELL", "curl --fail http://127.0.0.1:8000/api/health || exit 1"]
      interval: 5s
      retries: 30
  gotrue:
    image: appflowyinc/gotrue:latest
    restart: unless-stopped
    environment:
      GOTRUE_ADMIN_EMAIL: ${ADMIN_EMAIL}
      GOTRUE_ADMIN_PASSWORD: ${ADMIN_PASSWORD}
      GOTRUE_DISABLE_SIGNUP: "false"
      GOTRUE_SITE_URL: appflowy-flutter://
      GOTRUE_URI_ALLOW_LIST: "**"
      GOTRUE_JWT_SECRET: ${JWT_SECRET}
      GOTRUE_JWT_EXP: "604800"
      GOTRUE_JWT_ADMIN_GROUP_NAME: supabase_admin
      GOTRUE_DB_DRIVER: postgres
      API_EXTERNAL_URL: ${APPFLOWY_URL}/gotrue
      DATABASE_URL: postgres://postgres:${DB_PASSWORD}@postgres:5432/postgres?search_path=auth
      PORT: "9999"
      GOTRUE_MAILER_URLPATHS_CONFIRMATION: /gotrue/verify
      GOTRUE_MAILER_URLPATHS_INVITE: /gotrue/verify
      GOTRUE_MAILER_URLPATHS_RECOVERY: /gotrue/verify
      GOTRUE_MAILER_URLPATHS_EMAIL_CHANGE: /gotrue/verify
      GOTRUE_MAILER_AUTOCONFIRM: "true"
    depends_on:
      postgres:
        condition: service_healthy
    healthcheck:
      test: ["CMD-SHELL", "curl --fail http://127.0.0.1:9999/health || exit 1"]
      interval: 5s
      retries: 30
  admin_frontend:
    image: appflowyinc/admin_frontend:latest
    restart: unless-stopped
    environment:
      APPFLOWY_GOTRUE_BASE_URL: http://gotrue:9999
      APPFLOWY_BASE_URL: http://appflowy_cloud:8000
    depends_on:
      gotrue:
        condition: service_healthy
      appflowy_cloud:
        condition: service_healthy
  appflowy_worker:
    image: appflowyinc/appflowy_worker:latest
    restart: unless-stopped
    environment:
      RUST_LOG: info
      APPFLOWY_ENVIRONMENT: production
      APPFLOWY_WORKER_ENVIRONMENT: production
      APPFLOWY_WORKER_REDIS_URL: redis://redis:6379
      APPFLOWY_WORKER_DATABASE_URL: postgres://postgres:${DB_PASSWORD}@postgres:5432/postgres
      APPFLOWY_WORKER_DATABASE_NAME: postgres
      APPFLOWY_WORKER_IMPORT_TICK_INTERVAL: "30"
      APPFLOWY_S3_USE_MINIO: "true"
      APPFLOWY_S3_MINIO_URL: http://minio:9000
      APPFLOWY_S3_ACCESS_KEY: minio
      APPFLOWY_S3_SECRET_KEY: ${MINIO_PASSWORD}
      APPFLOWY_S3_BUCKET: appflowy
      APPFLOWY_S3_REGION: us-east-1
    depends_on:
      appflowy_cloud:
        condition: service_healthy
  appflowy_search:
    image: appflowyinc/appflowy_search:latest
    restart: unless-stopped
    environment:
      RUST_LOG: info
      APPFLOWY_SEARCH_HOST: "[::]"
      APPFLOWY_SEARCH_PORT: "4002"
      APPFLOWY_SEARCH_DATABASE_URL: postgres://postgres:${DB_PASSWORD}@postgres:5432/postgres
      APPFLOWY_SEARCH_REDIS_URL: redis://redis:6379
      APPFLOWY_S3_USE_MINIO: "true"
      APPFLOWY_S3_MINIO_URL: http://minio:9000
      APPFLOWY_S3_ACCESS_KEY: minio
      APPFLOWY_S3_SECRET_KEY: ${MINIO_PASSWORD}
      APPFLOWY_S3_BUCKET: appflowy
      APPFLOWY_S3_REGION: us-east-1
      APPFLOWY_BACKGROUND_INDEXER_ENABLED: "true"
      APPFLOWY_INDEXER_DATABASE_ENABLED: "false"
      APPFLOWY_KEYWORD_SEARCH_ENABLED: "true"
      APPFLOWY_KEYWORD_WORKER_ENABLED: "true"
      APPFLOWY_KEYWORD_INDEX_DIR: /var/lib/appflowy/keyword_index
      APPFLOWY_GOTRUE_JWT_SECRET: ${JWT_SECRET}
    volumes:
      - keyword-index:/var/lib/appflowy/keyword_index
    # Waits for the API service, which runs the database migrations.
    depends_on:
      appflowy_cloud:
        condition: service_healthy
  postgres:
    image: pgvector/pgvector:pg16
    restart: unless-stopped
    environment:
      POSTGRES_USER: postgres
      POSTGRES_PASSWORD: ${DB_PASSWORD}
      POSTGRES_DB: postgres
    volumes:
      - postgres-data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U postgres -d postgres"]
      interval: 5s
      retries: 20
  redis:
    image: redis:7-alpine
    restart: unless-stopped
    volumes:
      - redis-data:/data
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 5s
      retries: 10
  minio:
    image: cgr.dev/chainguard/minio:latest
    restart: unless-stopped
    command: server /data --address ":9000" --console-address ":9001"
    environment:
      MINIO_ROOT_USER: minio
      MINIO_ROOT_PASSWORD: ${MINIO_PASSWORD}
    volumes:
      - minio-data:/data
    healthcheck:
      test: ["CMD", "mc", "ready", "local"]
      interval: 5s
      retries: 20
configs:
  nginx-conf:
    content: |
      events {
        worker_connections 1024;
      }
      http {
        resolver 127.0.0.11 valid=10s;
        map $$http_upgrade $$connection_upgrade {
          default upgrade;
          '' close;
        }
        server {
          listen 80;
          client_max_body_size 10M;
          underscores_in_headers on;
          set $$cloud "http://appflowy_cloud:8000";
          set $$gotrue "http://gotrue:9999";
          set $$admin "http://admin_frontend:3000";
          set $$web "http://appflowy_web:80";
          set $$minio "http://minio:9000";
          location /gotrue/ {
            proxy_pass $$gotrue;
            rewrite ^/gotrue(/.*)$$ $$1 break;
            proxy_set_header Host $$http_host;
          }
          location /ws {
            proxy_pass $$cloud;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $$http_upgrade;
            proxy_set_header Connection "Upgrade";
            proxy_set_header Host $$host;
            proxy_read_timeout 86400s;
          }
          location /api {
            proxy_pass $$cloud;
            proxy_set_header X-Request-Id $$request_id;
            proxy_set_header Host $$http_host;
            location ~* ^/api/workspace/([a-zA-Z0-9_-]+)/publish$$ {
              proxy_pass $$cloud;
              proxy_request_buffering off;
              client_max_body_size 256M;
            }
            location /api/chat {
              proxy_pass $$cloud;
              proxy_http_version 1.1;
              proxy_set_header Connection "";
              chunked_transfer_encoding on;
              proxy_buffering off;
              proxy_cache off;
              proxy_read_timeout 600s;
            }
            location /api/import {
              proxy_pass $$cloud;
              proxy_set_header X-Request-Id $$request_id;
              proxy_set_header Host $$http_host;
              proxy_read_timeout 600s;
              proxy_request_buffering off;
              proxy_buffering off;
              client_max_body_size 2G;
            }
          }
          location /minio-api/ {
            proxy_pass $$minio;
            proxy_set_header Host minio:9000;
            rewrite ^/minio-api/(.*) /$$1 break;
            proxy_read_timeout 600s;
            proxy_request_buffering off;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            client_max_body_size 0;
          }
          location /ai/ {
            proxy_pass $$cloud;
            proxy_set_header X-Request-Id $$request_id;
            proxy_set_header Host $$http_host;
          }
          location /console {
            proxy_pass $$admin;
            proxy_set_header X-Forwarded-Host $$http_host;
            proxy_set_header Host $$http_host;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $$http_upgrade;
            proxy_set_header Connection $$connection_upgrade;
          }
          location / {
            proxy_pass $$web;
            proxy_set_header Host $$host;
          }
        }
      }
volumes:
  keyword-index:
  postgres-data:
  redis-data:
  minio-data:

services:
  caddy:
    image: caddy:2-alpine
    restart: unless-stopped
    configs:
      - source: caddyfile
        target: /etc/caddy/Caddyfile
    volumes:
      - chibisafe-uploads:/app/uploads:ro
    depends_on:
      - chibisafe
      - chibisafe-server
  chibisafe:
    image: chibisafe/chibisafe:v6.5.5
    restart: unless-stopped
    environment:
      BASE_API_URL: http://chibisafe-server:8000
  chibisafe-server:
    image: chibisafe/chibisafe-server:v6.5.5
    restart: unless-stopped
    volumes:
      - chibisafe-database:/app/database
      - chibisafe-uploads:/app/uploads
      - chibisafe-logs:/app/logs
configs:
  caddyfile:
    content: |
      :80 {
        route {
          file_server * {
            root /app/uploads
            pass_thru
          }
          @api path /api/*
          reverse_proxy @api http://chibisafe-server:8000 {
            header_up Host {http.reverse_proxy.upstream.hostport}
          }
          @docs path /docs*
          reverse_proxy @docs http://chibisafe-server:8000 {
            header_up Host {http.reverse_proxy.upstream.hostport}
          }
          reverse_proxy http://chibisafe:8001 {
            header_up Host {http.reverse_proxy.upstream.hostport}
          }
        }
      }
volumes:
  chibisafe-database:
  chibisafe-uploads:
  chibisafe-logs:

services:
  classicpress:
    image: classicpress/classicpress:latest
    restart: unless-stopped
    environment:
      CLASSICPRESS_DB_HOST: ${CLASSICPRESS_DB_HOST}
      CLASSICPRESS_DB_USER: ${CLASSICPRESS_DB_USER}
      CLASSICPRESS_DB_PASSWORD: ${CLASSICPRESS_DB_PASSWORD}
      CLASSICPRESS_DB_NAME: ${CLASSICPRESS_DB_NAME}
    volumes:
      - classicpress-files:/var/www/html
volumes:
  classicpress-files:

services:
  app:
    image: invoiceninja/invoiceninja-debian:5
    restart: unless-stopped
    environment:
      APP_URL: ${APP_URL}
      APP_KEY: ${APP_KEY}
      APP_ENV: production
      APP_DEBUG: "false"
      REQUIRE_HTTPS: "false"
      TRUSTED_PROXIES: "*"
      IS_DOCKER: "true"
      PDF_GENERATOR: snappdf
      FILESYSTEM_DISK: debian_docker
      CACHE_DRIVER: redis
      QUEUE_CONNECTION: redis
      SESSION_DRIVER: redis
      REDIS_HOST: redis
      REDIS_PORT: "6379"
      DB_CONNECTION: mysql
      DB_HOST: mysql
      DB_PORT: "3306"
      DB_DATABASE: ninja
      DB_USERNAME: ninja
      DB_PASSWORD: ${DB_PASSWORD}
      IN_USER_EMAIL: ${ADMIN_EMAIL}
      IN_PASSWORD: ${ADMIN_PASSWORD}
      MAIL_MAILER: log
    volumes:
      - app-public:/var/www/html/public
      - app-storage:/var/www/html/storage
    depends_on:
      mysql:
        condition: service_healthy
      redis:
        condition: service_healthy
  nginx:
    image: nginx:alpine
    restart: unless-stopped
    configs:
      - source: nginx-conf
        target: /etc/nginx/conf.d/default.conf
    volumes:
      - app-public:/var/www/html/public:ro
      - app-storage:/var/www/html/storage:ro
    depends_on:
      app:
        condition: service_healthy
  mysql:
    image: mysql:8.4
    restart: unless-stopped
    environment:
      MYSQL_ROOT_PASSWORD: ${DB_PASSWORD}
      MYSQL_DATABASE: ninja
      MYSQL_USER: ninja
      MYSQL_PASSWORD: ${DB_PASSWORD}
    volumes:
      - mysql-data:/var/lib/mysql
    healthcheck:
      test: ["CMD-SHELL", "mysqladmin ping -h 127.0.0.1 -uroot -p$$MYSQL_ROOT_PASSWORD --silent"]
      interval: 5s
      retries: 20
  redis:
    image: redis:7-alpine
    restart: unless-stopped
    volumes:
      - redis-data:/data
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 5s
      retries: 10
configs:
  nginx-conf:
    content: |
      client_max_body_size 10M;
      client_body_buffer_size 10M;
      server_tokens off;
      fastcgi_buffers 32 16K;
      gzip on;
      gzip_comp_level 2;
      gzip_min_length 1M;
      gzip_proxied any;
      gzip_types *;

      server {
          listen 80 default_server;
          server_name _;
          root /var/www/html/public;
          add_header X-Frame-Options "SAMEORIGIN";
          add_header X-Content-Type-Options "nosniff";
          index index.php;
          charset utf-8;

          location / {
              try_files $$uri $$uri/ /index.php?$$query_string;
          }
          location = /favicon.ico { access_log off; log_not_found off; }
          location = /robots.txt  { access_log off; log_not_found off; }
          error_page 404 /index.php;

          location ~ \.php$$ {
              fastcgi_pass app:9000;
              fastcgi_param SCRIPT_FILENAME $$realpath_root$$fastcgi_script_name;
              include fastcgi_params;
          }
          location ~ /\.(?!well-known).* {
              deny all;
          }
      }
volumes:
  app-public:
  app-storage:
  mysql-data:
  redis-data:

services:
  # Sends API, federation and image requests to the backend and the rest to the web UI.
  proxy:
    image: caddy:2-alpine
    restart: unless-stopped
    configs:
      - source: caddyfile
        target: /etc/caddy/Caddyfile
    depends_on:
      - lemmy
      - lemmy-ui
  lemmy:
    image: dessalines/lemmy:0.19.20
    restart: unless-stopped
    environment:
      RUST_LOG: warn
    configs:
      - source: lemmy-config
        target: /config/config.hjson
    depends_on:
      postgres:
        condition: service_healthy
      pictrs:
        condition: service_started
  lemmy-ui:
    image: dessalines/lemmy-ui:0.19.20
    restart: unless-stopped
    environment:
      LEMMY_UI_LEMMY_INTERNAL_HOST: lemmy:8536
      LEMMY_UI_LEMMY_EXTERNAL_HOST: ${LEMMY_HOST}
      LEMMY_UI_HTTPS: "true"
    depends_on:
      - lemmy
  pictrs:
    image: asonix/pictrs:0.5
    restart: unless-stopped
    user: 991:991
    environment:
      PICTRS__SERVER__API_KEY: ${PICTRS_API_KEY}
      PICTRS__MEDIA__VIDEO__ENABLE: "true"
      PICTRS__MEDIA__VIDEO__MAX_FILE_SIZE: "20"
      RUST_LOG: info
    volumes:
      - pictrs-data:/mnt
  postgres:
    image: postgres:17-alpine
    restart: unless-stopped
    shm_size: 256mb
    environment:
      POSTGRES_USER: lemmy
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: lemmy
    volumes:
      - postgres-data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U lemmy -d lemmy"]
      interval: 5s
      retries: 20
configs:
  lemmy-config:
    content: |
      {
        hostname: "${LEMMY_HOST}"
        database: {
          uri: "postgresql://lemmy:${POSTGRES_PASSWORD}@postgres:5432/lemmy"
        }
        pictrs: {
          url: "http://pictrs:8080/"
          api_key: "${PICTRS_API_KEY}"
        }
      }
  caddyfile:
    content: |
      {
        admin off
        auto_https off
        servers {
          trusted_proxies static private_ranges
        }
      }
      :80 {
        request_body {
          max_size 20MB
        }
        @backend {
          path /api/* /pictrs/* /feeds/* /nodeinfo/* /.well-known/* /version /sitemap.xml
        }
        @activitypub {
          method GET HEAD
          header_regexp Accept application/(activity|ld)\+json
        }
        @write {
          not method GET HEAD
        }
        handle @backend {
          reverse_proxy lemmy:8536
        }
        handle @activitypub {
          reverse_proxy lemmy:8536
        }
        handle @write {
          reverse_proxy lemmy:8536
        }
        handle {
          reverse_proxy lemmy-ui:1234
        }
      }
volumes:
  pictrs-data:
  postgres-data:

services:
  # LinkStack builds its links from the scheme it sees, so this talks to its HTTPS port.
  proxy:
    image: caddy:2-alpine
    restart: unless-stopped
    configs:
      - source: caddyfile
        target: /etc/caddy/Caddyfile
    depends_on:
      - linkstack
  linkstack:
    image: linkstackorg/linkstack:latest
    restart: unless-stopped
    environment:
      HTTP_SERVER_NAME: ${LINKSTACK_HOST}
      HTTPS_SERVER_NAME: ${LINKSTACK_HOST}
      SERVER_ADMIN: ${ADMIN_EMAIL}
      UPLOAD_MAX_FILESIZE: 16M
    volumes:
      - linkstack-data:/htdocs
configs:
  caddyfile:
    content: |
      {
        admin off
        auto_https off
      }
      :80 {
        reverse_proxy https://linkstack:443 {
          header_up Host {host}
          transport http {
            tls_insecure_skip_verify
          }
        }
      }
volumes:
  linkstack-data:

services:
  lldap:
    image: lldap/lldap:stable
    restart: unless-stopped
    environment:
      TZ: UTC
      LLDAP_JWT_SECRET: ${LLDAP_JWT_SECRET}
      LLDAP_KEY_SEED: ${LLDAP_KEY_SEED}
      LLDAP_LDAP_BASE_DN: ${LLDAP_LDAP_BASE_DN}
      LLDAP_LDAP_USER_PASS: ${LLDAP_LDAP_USER_PASS}
      LLDAP_HTTP_URL: ${LLDAP_HTTP_URL}
    volumes:
      - lldap-data:/data
volumes:
  lldap-data:

services:
  mailroom:
    image: ghcr.io/shahriyardx/mailroom:latest
    restart: unless-stopped
    environment:
      DATABASE_URL: postgres://mail:${POSTGRES_PASSWORD}@postgres:5432/mail
      APP_URL: ${APP_URL}
      BETTER_AUTH_URL: ${APP_URL}
      BETTER_AUTH_SECRET: ${BETTER_AUTH_SECRET}
      INBOUND_WEBHOOK_SECRET: ${INBOUND_WEBHOOK_SECRET}
      AWS_REGION: ${AWS_REGION}
      AWS_ACCESS_KEY_ID: ${AWS_ACCESS_KEY_ID}
      AWS_SECRET_ACCESS_KEY: ${AWS_SECRET_ACCESS_KEY}
      R2_ACCOUNT_ID: ${R2_ACCOUNT_ID}
      R2_ACCESS_KEY_ID: ${R2_ACCESS_KEY_ID}
      R2_SECRET_ACCESS_KEY: ${R2_SECRET_ACCESS_KEY}
      R2_BUCKET: ${R2_BUCKET}
    depends_on:
      postgres:
        condition: service_healthy
  postgres:
    image: postgres:18-alpine
    restart: unless-stopped
    environment:
      POSTGRES_USER: mail
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: mail
    volumes:
      - postgres-data:/var/lib/postgresql
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U mail -d mail"]
      interval: 5s
      retries: 20
volumes:
  postgres-data:

x-api-env: &api-env
  APP_NAME: OpnForm
  APP_ENV: production
  APP_KEY: ${APP_KEY}
  APP_DEBUG: "false"
  APP_URL: ${APP_URL}
  FRONT_URL: ${APP_URL}
  FRONT_API_SECRET: ${FRONT_API_SECRET}
  LOG_CHANNEL: errorlog
  LOG_LEVEL: warning
  FILESYSTEM_DRIVER: local
  LOCAL_FILESYSTEM_VISIBILITY: public
  CACHE_DRIVER: redis
  QUEUE_CONNECTION: redis
  SESSION_DRIVER: redis
  MAIL_MAILER: log
  REDIS_HOST: redis
  DB_CONNECTION: pgsql
  DB_HOST: postgres
  DB_DATABASE: opnform
  DB_USERNAME: opnform
  DB_PASSWORD: ${POSTGRES_PASSWORD}
  JWT_SECRET: ${JWT_SECRET}
  JWT_TTL: "1440"
  TRUSTED_PROXIES: "*"
  PHP_MEMORY_LIMIT: 1G
  PHP_MAX_EXECUTION_TIME: "600"
  PHP_UPLOAD_MAX_FILESIZE: 64M
  PHP_POST_MAX_SIZE: 64M
services:
  ingress:
    image: nginx:1
    restart: unless-stopped
    configs:
      - source: nginx-conf
        target: /etc/nginx/conf.d/default.conf
    depends_on:
      - api
      - ui
  api:
    image: jhumanj/opnform-api:2.5.0
    restart: unless-stopped
    environment: *api-env
    volumes:
      - opnform-storage:/usr/share/nginx/html/storage
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
  api-worker:
    image: jhumanj/opnform-api:2.5.0
    restart: unless-stopped
    command: ["php", "artisan", "queue:work"]
    environment: *api-env
    volumes:
      - opnform-storage:/usr/share/nginx/html/storage
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
  api-scheduler:
    image: jhumanj/opnform-api:2.5.0
    restart: unless-stopped
    command: ["php", "artisan", "schedule:work"]
    environment: *api-env
    volumes:
      - opnform-storage:/usr/share/nginx/html/storage
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
  ui:
    image: jhumanj/opnform-client:2.5.0
    restart: unless-stopped
    environment:
      NUXT_PUBLIC_APP_URL: /
      NUXT_PUBLIC_API_BASE: /api
      NUXT_PRIVATE_API_BASE: http://ingress/api
      NUXT_PUBLIC_ENV: production
      NUXT_API_SECRET: ${FRONT_API_SECRET}
  postgres:
    image: postgres:17-alpine
    restart: unless-stopped
    environment:
      POSTGRES_USER: opnform
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: opnform
    volumes:
      - postgres-data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U opnform -d opnform"]
      interval: 5s
      retries: 20
  redis:
    image: redis:7-alpine
    restart: unless-stopped
    volumes:
      - redis-data:/data
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 5s
      retries: 20
configs:
  nginx-conf:
    content: |
      map $$request_uri $$api_uri {
          ~^/api(/.*$$) $$1;
          default $$request_uri;
      }
      server {
          listen 80;
          root /usr/share/nginx/html/public;
          client_max_body_size 64m;
          index index.html index.htm index.php;
          location / {
              proxy_http_version 1.1;
              proxy_pass http://ui:3000;
              proxy_set_header X-Real-IP $$remote_addr;
              proxy_set_header X-Forwarded-Host $$host;
              proxy_set_header X-Forwarded-Port $$server_port;
              proxy_set_header Upgrade $$http_upgrade;
              proxy_set_header Connection "Upgrade";
          }
          location ~/(api|open|local\/temp|forms\/assets)/ {
              set $$original_uri $$uri;
              try_files $$uri $$uri/ /index.php$$is_args$$args;
          }
          location ~ \.php$$ {
              fastcgi_split_path_info ^(.+\.php)(/.+)$$;
              fastcgi_pass api:9000;
              fastcgi_index index.php;
              include fastcgi_params;
              fastcgi_param SCRIPT_FILENAME $$document_root/index.php;
              fastcgi_param REQUEST_URI $$api_uri;
              fastcgi_param HTTP_X_FORWARDED_FOR $$proxy_add_x_forwarded_for;
              fastcgi_param HTTP_X_FORWARDED_HOST $$http_x_forwarded_host;
              fastcgi_param HTTP_X_FORWARDED_PORT $$http_x_forwarded_port;
              fastcgi_param HTTP_X_FORWARDED_PROTO $$http_x_forwarded_proto;
          }
          location ~ /\. {
              deny all;
          }
      }
volumes:
  opnform-storage:
  postgres-data:
  redis-data:

services:
  soketi:
    image: quay.io/soketi/soketi:1.6-16-debian
    restart: unless-stopped
    environment:
      SOKETI_DEFAULT_APP_ID: ${SOKETI_APP_ID}
      SOKETI_DEFAULT_APP_KEY: ${SOKETI_APP_KEY}
      SOKETI_DEFAULT_APP_SECRET: ${SOKETI_APP_SECRET}

services:
  wordpress:
    image: wordpress:6-apache
    restart: unless-stopped
    environment:
      WORDPRESS_DB_HOST: ${WORDPRESS_DB_HOST}
      WORDPRESS_DB_USER: ${WORDPRESS_DB_USER}
      WORDPRESS_DB_PASSWORD: ${WORDPRESS_DB_PASSWORD}
      WORDPRESS_DB_NAME: ${WORDPRESS_DB_NAME}
    volumes:
      - wp-content:/var/www/html
volumes:
  wp-content:
